import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"35、【晋】 坤下离上","description":"周易尚氏学 - 35、【晋】 坤下离上","frontmatter":{"title":"35、【晋】 坤下离上","description":"周易尚氏学 - 35、【晋】 坤下离上"},"headers":[],"relativePath":"zh/classics/shangshi/040.md","filePath":"zh/classics/shangshi/040.md"}'),h={name:"zh/classics/shangshi/040.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_35、【晋】-坤下离上" tabindex="-1">35、【晋】 坤下离上 <a class="header-anchor" href="#_35、【晋】-坤下离上" aria-label="Permalink to “35、【晋】 坤下离上”">​</a></h1><p>离出地居五。南面响明而治。故曰晋。晋进也。四诸侯。康美也。大也。礼祭统。康周公注。康犹褒大也。易林随之恒云。实沉参虚。封为康侯。康侯略如大侯。为诸侯之美称。犹诗之言齐侯。言平王也。坎为马。坤亦为马。坎为众。坤亦为众。故曰用锡马蕃庶。艮为手故曰锡。锡予也。言康侯恭顺。来宾于王。锡贲众多。杂卦。晋昼也。艮为手。数三。离为昼。故曰昼日三接。侯果曰。大行人职曰。诸公三晌三问三劳。诸侯三响再问再劳。于男三晌一问一劳。即天子三接诸侯之礼也。昼日三接。即一昼三觌也。</p><p>彖曰。晋。进也。明出地上。顺而丽乎大明。柔进而上行。是以康候用锡马蕃庶。昼日三接也。</p><p>明出地上谓离。顺谓坤。柔进而上行谓五。进居地上。得君位也。</p><p>象曰。明出地上。晋。君子以自昭明德。</p><p>明出地上。自然显著德不求明而自明。故学易之君子。取法乎此。以自昭明德。言明德在已。自然昭朗。视能进与否耳。苟进而上行。未有不显著者。昭正义云。周氏等作</p><p>初六。晋如摧如。贞吉。同孚 裕无咎。</p><p>初阴。二三亦阴。得敌。故进而见摧。有应故贞吉。然初虽应四。以为二三所隔。应之甚难。故曰罔孚。裕缓也。言初与四终为正应。缓以俟之。则无咎也。与屯六二。十年乃字义同也。旧解皆不知得敌之理。虞翻以失位诂摧如。以罔罟诂罔孚。遂歧误百出矣。</p><h3 id="象曰。晋如摧如。独行正也。裕无咎。未受命也。" tabindex="-1">象曰。晋如摧如。独行正也。裕无咎。未受命也。 <a class="header-anchor" href="#象曰。晋如摧如。独行正也。裕无咎。未受命也。" aria-label="Permalink to “象曰。晋如摧如。独行正也。裕无咎。未受命也。”">​</a></h3><p>初阴遇阴得敌。故曰独行。有应故曰正未受命者。言初居勿用之位。尚未膺官守之命也。</p><p>六二。晋如愁如。贞吉。受兹介福于其王母。</p><p>二无应。进遇坎。坎为忧。故曰愁如。贞吉者。卜问吉也。介虞九家皆训为大。坤为母。伏乾为大为福为王。故曰受兹介福于其王母。王母谓二。言二虽不宜于进。然得中为坤本位。必受此大福也。旧解谓王母指六五。六五亦阴。焉能福二。故夫阴遇阴阳遇阳。敌应之理不明。说易无不误也。</p><h3 id="象曰。受兹介福。以中正也。" tabindex="-1">象曰。受兹介福。以中正也。 <a class="header-anchor" href="#象曰。受兹介福。以中正也。" aria-label="Permalink to “象曰。受兹介福。以中正也。”">​</a></h3><p>言二所以受兹大福者。以得此中正之位也。若六五则中而不正。各家因曰王母疑非五莫能当。岂知下坤方为母，伏乾故曰王母。易林此例甚多也。</p><p>六三。众允悔亡。</p><p>施氏于升初六允升。读作允（a：左上山左下卒）。就允（a）进也。此允字当与之同。故吴澄亦读作众允（a）。众斯允（a）者众进。坤为众。言群阴并进而承阳也。故曰悔亡。虞翻诂允为信。朱子从之。与象传上行之义不合。</p><h3 id="象曰。众克之志。上行也。" tabindex="-1">象曰。众克之志。上行也。 <a class="header-anchor" href="#象曰。众克之志。上行也。" aria-label="Permalink to “象曰。众克之志。上行也。”">​</a></h3><p>坎为志。上行谓进而承阳。即释允（a）义。可见施读合也。</p><p>九四。晋如鼠。贞厉。</p><p>释文子夏传作硕鼠。云五技鼠也。古盖音同通用。艮为鼠。为穴。坎为盗。鼠居穴中。伺隙盗窃。昼伏夜动。四失位。前临夷主。下拥万民。而坎为隐伏。为畏怯。欲进居五。恐下民生疑。欲下应初。又恐失五位。进退周章。有类于硕鼠。故贞厉也。</p><h3 id="象曰。硕鼠贞厉。位不当也。" tabindex="-1">象曰。硕鼠贞厉。位不当也。 <a class="header-anchor" href="#象曰。硕鼠贞厉。位不当也。" aria-label="Permalink to “象曰。硕鼠贞厉。位不当也。”">​</a></h3><p>位不当。即谓不中不正。</p><p>六五。悔亡。矢得勿恤。往吉。无不利。</p><p>六五得尊位。晌明而治。故侮亡。矢辅嗣作失。兹从孟马荀虞郑王肃诸家。坎为矢。五坎体。是得矢也。坎为恤。得矢为用。故勿恤。承阳故往吉。坎矢象。噬嗑九四云得金矢。以坎为失也。易林常用。乃至汉末竟失传。</p><h3 id="象曰。矢得勿恤。往有庆也。" tabindex="-1">象曰。矢得勿恤。往有庆也。 <a class="header-anchor" href="#象曰。矢得勿恤。往有庆也。" aria-label="Permalink to “象曰。矢得勿恤。往有庆也。”">​</a></h3><p>往遇阳。故曰往有庆。虞翻强命五变得乾为有庆。岂知六五上下皆乾阳。五居其中。往承阳故有庆。若五变为阳。往遇阳得敌。尚能有庆哉。</p><p>上九。晋其角。维用伐邑。厉吉。无咎。贞吝。</p><p>爻例上为角。故曰晋其角。坤为邑。离上九云。王用出征。有嘉折首。是离有征伐象。盖离为甲兵。故维用代色。然下应柔爻。故必振厉方吉元咎。以不全吉。故贞吝。</p><h3 id="象曰。维用伐邑。道未光也。" tabindex="-1">象曰。维用伐邑。道未光也。 <a class="header-anchor" href="#象曰。维用伐邑。道未光也。" aria-label="Permalink to “象曰。维用伐邑。道未光也。”">​</a></h3><p>离为光明。至上光将熄矣。夫王道大光。则无用征伐。用征伐必未光也。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
